-- PT118-S4-Q11. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT118-S4-Q11$batch13$ AND q.stimulus=$batch13$Between 1976 and 1985, chemical wastes were dumped into Cod Bay. Today, 3 percent of the bay’s bluefin cod population have deformed fins, and wary consumers have stopped buying the fish. In seeking financial reparations from companies that dumped the chemicals, representatives of Cod Bay’s fishing industry have claimed that since the chemicals are known to cause genetic mutations, the deformity in the bluefin cod must have been caused by the presence of those chemicals in Cod Bay.$batch13$ AND q.prompt=$batch13$The answer to each of the following questions would be helpful in evaluating the representatives' claim EXCEPT:$batch13$ AND q.correct_choice=$batch13$C$batch13$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT118-S4-Q11$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT118-S4-Q11$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$The chemicals dumped into Cod Bay caused the deformed fins.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$The chemicals cause genetic mutations. Three percent of the bay's cod now have deformed fins.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$This is an EXCEPT question. Four questions test the causal claim: the normal rate of deformity, the rate before dumping, other natural causes, and other pollutants. The answer is about something the claim doesn't depend on.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find the question whose answer wouldn't bear on what caused the deformities.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT118-S4-Q11$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$If unexposed cod have deformities at the same rate, the chemicals may not be the cause.$batch13$), ($batch13$B$batch13$, $batch13$A before-and-after comparison shows whether the dumping changed anything.$batch13$), ($batch13$C$batch13$, $batch13$Whether eating the fish made people sick has nothing to do with what caused the deformities.$batch13$), ($batch13$D$batch13$, $batch13$A natural disease would be another explanation.$batch13$), ($batch13$E$batch13$, $batch13$Other gene-altering pollutants could be the cause instead.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT118-S4-Q11$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
